css:
.resume{--bg: #0a0c0f;
      --surface: #13171c;
      --border: #2a3038;
      --text-primary: #e1e4e8;
      --text-secondary: #b0b8c1;
      --text-muted: #6e7681;
      --accent-green: #3fb950;
      --accent-blue: #58a6ff;
      --accent-orange: #d2991d;
      --accent-red: #f85149;
      --highlight-line: #1f6feb;
      --code-bg: #161b22;
      --font-mono: 'SF Mono', 'Cascadia Code', 'Consolas', 'Fira Code', 'Courier New', monospace;
      --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Helvetica Neue', Arial, '思源黑体', 'Noto Sans SC', sans-serif;}
.resume{max-width: 210mm;
      width: 100%;
      background-color: var(--bg);
      border: 1px solid var(--border);
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.7);
      padding: 0.75in 0.8in;
      margin: 0 auto;
      font-size: 10.5pt;
      color: var(--text-primary);
      position: relative;}
.cli-prefix{color: var(--accent-green);
      font-family: var(--font-mono);
      font-weight: 400;
      margin-right: 0.25rem;
      user-select: none;}
.resume h1, .resume h2, .resume h3, .resume p, .resume li, .resume span, .resume div{color: inherit;}
.resume a{color: var(--accent-blue);
      text-decoration: none;}
.resume h1{font-size: 26pt;
      font-weight: 600;
      letter-spacing: 0.5px;
      color: #ffffff;
      margin-bottom: 0.1rem;
      font-family: var(--font-mono);
      border-bottom: 1px solid var(--border);
      padding-bottom: 0.2rem;}
.title-sub{font-size: 12pt;
      color: var(--accent-blue);
      font-family: var(--font-mono);
      margin-bottom: 0.9rem;
      font-weight: 400;}
.section-title{font-size: 11pt;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: var(--accent-green);
      margin-top: 1.3rem;
      margin-bottom: 0.6rem;
      border-bottom: 1px solid var(--border);
      padding-bottom: 0.15rem;
      font-family: var(--font-mono);
      display: flex;
      align-items: center;
      gap: 0.3rem;}
.section-title::before{content: "❯";
      color: var(--accent-green);
      font-weight: 400;
      font-size: 10pt;}
.exp-item{margin-bottom: 0.7rem;}
.exp-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.15rem;}
.company{font-weight: 700;
      font-size: 11pt;
      color: #ffffff;
      font-family: var(--font-sans);}
.role{font-weight: 500;
      color: var(--text-secondary);
      margin-left: 0.3rem;
      font-size: 10.5pt;}
.date{font-family: var(--font-mono);
      color: var(--text-muted);
      font-size: 9.5pt;
      white-space: nowrap;}
.desc-list{list-style: none;
      padding-left: 0;
      margin-top: 0.2rem;
      color: var(--text-secondary);}
.desc-list li{position: relative;
      padding-left: 1.2rem;
      margin-bottom: 0.2rem;
      font-size: 10pt;}
.desc-list li::before{content: "•";
      position: absolute;
      left: 0.2rem;
      color: var(--accent-orange);
      font-weight: bold;
      font-family: monospace;}
.skill-tags{display: flex;
      flex-wrap: wrap;
      gap: 0.4rem;
      margin-top: 0.2rem;}
.tag{background-color: var(--surface);
      border: 1px solid var(--border);
      color: var(--text-primary);
      padding: 0.2rem 0.7rem;
      border-radius: 4px;
      font-size: 9.5pt;
      font-family: var(--font-mono);
      white-space: nowrap;}
.tag strong{color: var(--accent-blue);
      font-weight: 500;
      margin-right: 0.2rem;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;
      margin: 0.5rem 0 0.2rem;
      font-family: var(--font-mono);
      font-size: 9.5pt;
      color: var(--text-secondary);
      border-bottom: 1px dashed var(--border);
      padding-bottom: 0.5rem;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.icon-symbol{color: var(--accent-green);
      font-weight: 400;}
.two-col{display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1rem;
      margin-top: 0.3rem;}
.col{display: flex;
      flex-direction: column;}
.resume hr{border: none;
      border-top: 1px solid var(--border);
      margin: 0.5rem 0 0.2rem;}
.edu-item{display: flex;
      justify-content: space-between;
      margin-bottom: 0.25rem;
      font-size: 10pt;}
.school-name{font-weight: 600;
      color: #ffffff;}
.degree{color: var(--text-secondary);
      margin-left: 0.4rem;}

.resume{font-family:var(--font-sans)}.resume-title{font-size:9pt;letter-spacing:0.1em;color:var(--text-muted);margin-bottom:8px;font-family:var(--font-mono)}.tool-line{display:flex;flex-wrap:wrap;gap:8px;margin-top:0.5rem;font-size:9.5pt;color:var(--text-muted)}.tool-item{margin-right:4px}.cert-line{display:flex;flex-wrap:wrap;gap:1.5rem;font-size:10pt}.cert-item{display:inline-flex;gap:4px}.cert-icon{color:var(--accent-green)}
